package com.pawcare.publicapi.ai;

import com.pawcare.publicapi.audit.AuditService;
import com.pawcare.publicapi.auth.CurrentPrincipal;
import com.pawcare.publicapi.auth.CurrentUser;
import com.pawcare.publicapi.web.ApiException;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

/** Human review only: no endpoint changes a transaction, account, schema, or data subject. */
@RestController @RequestMapping("/api/v1/admin/ai")
public class AiAdminController {
 private final JdbcTemplate db; private final AuditService audit;
 public AiAdminController(JdbcTemplate db,AuditService audit){this.db=db;this.audit=audit;}
 @GetMapping("/risk-scores") public Map<String,Object> scores(@CurrentUser CurrentPrincipal p,@RequestParam(required=false)String riskLevel,@RequestParam(required=false)String reviewStatus,@RequestParam(required=false)String type,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){admin(p);page(page,size);StringBuilder sql=new StringBuilder("SELECT id,aggregate_type,aggregate_id,model_name,model_version,risk_score,risk_level,explanation_summary,scored_at,review_status,reviewer_profile_id,reviewed_at,reviewer_note FROM ai_risk_scores WHERE 1=1");List<Object>a=new ArrayList<>(); if(valid(riskLevel,Set.of("LOW","MEDIUM","HIGH"))){sql.append(" AND risk_level=?");a.add(riskLevel.toUpperCase());}if(valid(reviewStatus,Set.of("OPEN","REVIEWED","DISMISSED"))){sql.append(" AND review_status=?");a.add(reviewStatus.toUpperCase());}if(type!=null&&!type.isBlank()){sql.append(" AND aggregate_type=?");a.add(type.toUpperCase());}sql.append(" ORDER BY scored_at DESC,id DESC LIMIT ? OFFSET ?");a.add(size);a.add(page*size);return Map.of("items",db.queryForList(sql.toString(),a.toArray()),"page",page,"size",size);}
 @GetMapping("/risk-scores/{id}") public Map<String,Object> score(@CurrentUser CurrentPrincipal p,@PathVariable long id){admin(p);Map<String,Object>x=one("SELECT id,aggregate_type,aggregate_id,model_name,model_version,risk_score,risk_level,explanation_summary,feature_snapshot,scored_at,review_status,reviewer_profile_id,reviewed_at,reviewer_note FROM ai_risk_scores WHERE id=?",id);if(x==null)throw new ApiException(404,"Risk score not found");return x;}
 @PutMapping("/risk-scores/{id}/review") @Transactional public Map<String,Object> reviewScore(@CurrentUser CurrentPrincipal p,@PathVariable long id,@RequestBody Map<String,Object>b){admin(p);String status=text(b,"status");if(!Set.of("OPEN","REVIEWED","DISMISSED").contains(status))throw new ApiException(400,"Invalid review status");if(one("SELECT id FROM ai_risk_scores WHERE id=? FOR UPDATE",id)==null)throw new ApiException(404,"Risk score not found");db.update("UPDATE ai_risk_scores SET review_status=?,reviewer_profile_id=?,reviewed_at=CURRENT_TIMESTAMP,reviewer_note=? WHERE id=?",status,p.profileId(),trim(text(b,"reviewerNote"),1000),id);audit.record(p.profileId(),"AI_RISK_REVIEW", "AI_RISK_SCORE",id,Map.of("status",status));return Map.of("id",id,"status",status);}
 @GetMapping("/operational-recommendations") public List<Map<String,Object>> recommendations(@CurrentUser CurrentPrincipal p,@RequestParam(required=false)String status){admin(p);if(status==null||status.isBlank())return db.queryForList("SELECT r.id,r.recommendation_type,r.subject_name,r.model_name,r.model_version,r.score,r.confidence,r.payload,r.status,r.created_at,r.reviewer_profile_id,r.reviewed_at,r.reviewer_note,u.full_name reviewer_name FROM ai_operational_recommendations r LEFT JOIN user_profiles u ON u.id=r.reviewer_profile_id ORDER BY r.created_at DESC,r.id DESC");return db.queryForList("SELECT r.id,r.recommendation_type,r.subject_name,r.model_name,r.model_version,r.score,r.confidence,r.payload,r.status,r.created_at,r.reviewer_profile_id,r.reviewed_at,r.reviewer_note,u.full_name reviewer_name FROM ai_operational_recommendations r LEFT JOIN user_profiles u ON u.id=r.reviewer_profile_id WHERE r.status=? ORDER BY r.created_at DESC,r.id DESC",status.toUpperCase());}
 @PutMapping("/operational-recommendations/{id}/review") @Transactional public Map<String,Object> reviewRecommendation(@CurrentUser CurrentPrincipal p,@PathVariable long id,@RequestBody Map<String,Object>b){admin(p);String status=text(b,"status");if(!Set.of("OPEN","REVIEWED","DISMISSED","APPROVED").contains(status))throw new ApiException(400,"Invalid review status");if(one("SELECT id FROM ai_operational_recommendations WHERE id=? FOR UPDATE",id)==null)throw new ApiException(404,"Recommendation not found");db.update("UPDATE ai_operational_recommendations SET status=?,reviewer_profile_id=?,reviewed_at=CURRENT_TIMESTAMP,reviewer_note=? WHERE id=?",status,p.profileId(),trim(text(b,"reviewerNote"),1000),id);audit.record(p.profileId(),"AI_OPERATIONAL_RECOMMENDATION_REVIEW","AI_OPERATIONAL_RECOMMENDATION",id,Map.of("status",status));return Map.of("id",id,"status",status);}
 private void admin(CurrentPrincipal p){if(!"ADMIN".equals(p.role()))throw new ApiException(403,"Admin account required");}private void page(int p,int s){if(p<0||s<1||s>200)throw new ApiException(400,"Invalid pagination");}private boolean valid(String v,Set<String>s){if(v==null||v.isBlank())return false;if(!s.contains(v.toUpperCase()))throw new ApiException(400,"Invalid filter");return true;}private Map<String,Object>one(String s,Object...a){var r=db.queryForList(s,a);return r.isEmpty()?null:r.get(0);}private String text(Map<String,Object>b,String k){return b.get(k)==null?null:String.valueOf(b.get(k)).trim();}private String trim(String x,int n){return x==null?null:x.length()>n?x.substring(0,n):x;}
}
